def comps(g,v):
    seen=set(); out=[]
    H,W=len(g),len(g[0])
    for r in range(H):
        for c in range(W):
            if g[r][c]==v and (r,c) not in seen:
                st=[(r,c)]; comp=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen or 0<=a<H and 0<=b<W and g[a][b]==v: pass
                    else: continue
                # simpler
                st=[(r,c)]; comp=[]
                seen.add((r,c))
                while st:
                    a,b=st.pop()
                    comp.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<H and 0<=y<W and g[x][y]==v and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                out.append(comp)
    return out
