    seen=set(); out=[]; H,W=len(g),len(g[0])
    for r in range(H):
        for c2 in range(W):
            if g[r][c2]==v and (r,c2) not in seen:
                st=[(r,c2)]; comp=[]; seen.add((r,c2))
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<H and 0<=y<W and g[x][y]==v and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                out.append(comp)
    return out
def sign(c):
    rs=[a for a,_ in c]; cs2=[b for _,b in c]
    H=max(rs)-min(rs)+1; W=max(cs2)-min(cs2)+1
    m=[[0]*W for _ in range(H)]
    for a,b in c: m[a-min(rs)][b-min(cs2)]=1
    return tuple(tuple(row) for row in m)
