from collections import defaultdict
def comps(g,v):
    seen=set(); out=[]; H,W=len(g),len(g[0])
    for r in range(H):
        for c2 in range(W):
            if g[r][c2]==v and (r,c2) not in seen:
                st=[(r,c2)]; comp=[]; seen.add((r,c2))
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<H and 0<=y<W and g[x][y]==v and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                out.append(comp)
    return out
def sign(C):
    rs=[a for a,_ in C]; cs=[b for _,b in C]
    m=[[0]*(max(cs)-min(cs)+1) for _ in range(max(rs)-min(rs)+1)]
    for a,b in C: m[a-min(rs)][b-min(cs)]=1
    return tuple(map(tuple,m))
def mindist(A,B): return min(abs(a-x)+abs(b-y) for a,b in A for x,y in B)
def f(g):
    allc=[(v,C) for v in sorted(set(x for r in g for x in r)) for C in comps(g,v)]
    by=defaultdict(list)
    for v,C in allc: by[sign(C)].append((v,C))
    grp=max(by.values(), key=lambda M: sum(len(C) for _,C in M))
